Create a Node.js script to automate a daily backup of a MongoDB database.
MongoDB URI: mongodb+srv://<user>:<password>@<cluster-name>/<database-name>
Backup location: ./backup

Here's a Node.js script that automates daily MongoDB database backups:

```javascript
/**
 * MongoDB Daily Backup Script
 * 
 * This script automates daily backups of a MongoDB database.
 * It uses mongodump to create backups and node-schedule for scheduling.
 */

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');
const schedule = require('node-schedule');

// Configuration
const mongoURI = 'mongodb+srv://<user>:<password>@<cluster-name>/<database-name>';
const backupDir = './backup';

// Ensure backup directory exists
if (!fs.existsSync(backupDir)) {
  fs.mkdirSync(backupDir, { recursive: true });
  console.log(`Created backup directory: ${backupDir}`);
}

/**
 * Function to perform the MongoDB backup
 */
function performBackup() {
  // Create a timestamp for the backup folder
  const timestamp = new Date().toISOString().replace(/:/g, '-');
  const backupPath = path.join(backupDir, `backup-${timestamp}`);

  console.log(`Starting MongoDB backup to: ${backupPath}`);

  // Execute mongodump command
  exec(`mongodump --uri="${mongoURI}" --out="${backupPath}"`, (error, stdout, stderr) => {
    if (error) {
      console.error(`Backup failed: ${error.message}`);
      return;
    }

    if (stderr) {
      console.error(`Backup stderr: ${stderr}`);
      return;
    }

    console.log(`Backup completed successfully: ${stdout}`);

    // Optional: Compress the backup
    compressBackup(backupPath);
  });
}

/**
 * Compress the backup folder to save space
 * @param {string} backupPath - Path to the backup folder
 */
function compressBackup(backupPath) {
  console.log(`Compressing backup: ${backupPath}`);

  exec(`tar -czf "${backupPath}.tar.gz" -C "${path.dirname(backupPath)}" "${path.basename(backupPath)}"`, (error, stdout, stderr) => {
    if (error) {
      console.error(`Compression failed: ${error.message}`);
      return;
    }

    console.log(`Backup compressed successfully`);

    // Optional: Remove the uncompressed folder
    fs.rmSync(backupPath, { recursive: true, force: true });
    console.log(`Removed uncompressed backup folder`);
  });
}

/**
 * Clean up old backups (keep last 7 days)
 */
function cleanupOldBackups() {
  console.log('Cleaning up old backups...');

  fs.readdir(backupDir, (err, files) => {
    if (err) {
      console.error(`Error reading backup directory: ${err.message}`);
      return;
    }

    const now = new Date();
    const sevenDaysAgo = new Date(now.setDate(now.getDate() - 7));

    files.forEach(file => {
      const filePath = path.join(backupDir, file);

      // Get file stats
      fs.stat(filePath, (err, stats) => {
        if (err) {
          console.error(`Error getting file stats: ${err.message}`);
          return;
        }

        // Check if file is older than 7 days
        if (stats.mtime < sevenDaysAgo) {
          if (stats.isDirectory()) {
            fs.rmSync(filePath, { recursive: true, force: true });
          } else {
            fs.unlinkSync(filePath);
          }
          console.log(`Deleted old backup: ${file}`);
        }
      });
    });
  });
}

// Schedule daily backup at 1:00 AM
const backupJob = schedule.scheduleJob('0 1 * * *', () => {
  console.log(`Running scheduled backup at ${new Date().toISOString()}`);
  performBackup();

  // Clean up old backups after creating a new one
  setTimeout(cleanupOldBackups, 60000); // Wait 1 minute before cleanup
});

// Run an initial backup when the script starts
performBackup();

console.log('MongoDB backup scheduler started. Backups will run daily at 1:00 AM.');

// Handle process termination
process.on('SIGINT', () => {
  console.log('Backup scheduler stopping...');
  backupJob.cancel();
  process.exit(0);
});

// Export functions for testing or manual execution
module.exports = {
  performBackup,
  cleanupOldBackups
};
```

To use this script:

1. Install the required dependencies:
```bash
npm init -y
npm install node-schedule
```

2. Make sure `mongodump` is installed on your system (part of MongoDB Database Tools)

3. Replace the placeholder values in the MongoDB URI with your actual credentials

4. Run the script:
```bash
node backup-script.js
```

The script will:
- Create an initial backup when started
- Schedule daily backups at 1:00 AM
- Compress backups to save space
- Automatically clean up backups older than 7 days
- Handle errors and log all operations

You can run this script as a background process or set it up as a service to ensure it runs continuously.
